/**
 * Utility to safely parse JSON from model responses that might be wrapped in markdown blocks.
 */
const safeJsonParse = (text: string) => {
  try {
    return JSON.parse(text);
  } catch (e) {
    const cleaned = text.replace(/```json\n?|```/g, '').trim();
    try {
      return JSON.parse(cleaned);
    } catch (e2) {
      console.error("Failed to parse JSON from response:", text);
      throw new Error("Invalid intelligence format received from node.");
    }
  }
};

/**
 * Robust retry mechanism with exponential backoff to handle 429 and 5xx errors.
 */
async function withRetry<T>(fn: () => Promise<T>, retries = 3, delay = 1000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    const isRetryable = error?.message?.includes('429') || 
                        error?.message?.includes('500') || 
                        error?.message?.includes('503') ||
                        error?.message?.includes('quota');

    if (retries > 0 && isRetryable) {
      console.warn(`API Rate Limit or Server Error. Retrying in ${delay}ms... (${retries} attempts left)`);
      await new Promise(resolve => setTimeout(resolve, delay));
      return withRetry(fn, retries - 1, delay * 2);
    }
    throw error;
  }
}

