      config: { responseMimeType: "application/json" },
    });
    return safeJsonParse(response.text);
  });
};

export function decodeBase64(base64: string) {
  const binaryString = atob(base64);
  const bytes = new Uint8Array(binaryString.length);
  for (let i = 0; i < binaryString.length; i++) bytes[i] = binaryString.charCodeAt(i);
  return bytes;
}

export async function decodeAudioData(data: Uint8Array, ctx: AudioContext): Promise<AudioBuffer> {
  const dataInt16 = new Int16Array(data.buffer);
  const sampleRate = 24000;
  const numChannels = 1;
  const frameCount = dataInt16.length / numChannels;
  const buffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = buffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return buffer;
}

import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, generateOperationalReport, generateSpeech } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, OperationalReport } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onOperationalReportGenerated?: (report: OperationalReport) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onOperationalReportGenerated }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [isReporting, setIsReporting] = useState(false);
  const [channelMode, setChannelMode] = useState<'voice' | 'chat'>('chat');
  const [activeMode, setActiveMode] = useState<"normal" | "honeypot">("normal");
  const [psychState, setPsychState] = useState({ greed: 10, suspicion: 5 });
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [initialMessages, isTyping, isSynthesizing]);

  const playAudio = async (text: string) => {
    setIsSynthesizing(true);
    try {
      const buffer = await generateSpeech(text);
      if (!audioContextRef.current) {
        audioContextRef.current = new (window.AudioContext || (window as any).webkitAudioContext)();
      }
      const source = audioContextRef.current.createBufferSource();
      source.buffer = buffer;
      source.connect(audioContextRef.current.destination);
      source.start();
      source.onended = () => setIsSynthesizing(false);
    } catch (e) {
      console.error("Audio playback error", e);
      setIsSynthesizing(false);
    }
  };

  const syncIntelligence = async (messages: ChatMessage[], intel: any) => {
    if (isReporting) return;
    setIsReporting(true);
    try {
      const log = messages.map(m => `${m.role.toUpperCase()}: ${m.content}`).join('\n');
      const report = await generateOperationalReport({ ...intel, id: sessionId }, log);
      if (onOperationalReportGenerated) onOperationalReportGenerated(report);
    } catch (e) {
      console.error("Intelligence sync failed", e);
    } finally {
      setIsReporting(false);
    }
  };

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(history, channelMode);

      setActiveMode(result.mode || "normal");
      if (result.psych_state) setPsychState(result.psych_state);

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.reply_to_scammer, 
        timestamp: Date.now(),
        extractedData: result.intel,
        psychState: result.psych_state
      }];

      onMessagesUpdate(updatedMessages);

      if (channelMode === 'voice') {
        playAudio(result.reply_to_scammer);
      }

      if (result.intel) {
        const info: ExtractedInfo = {
          upiIds: result.intel.upi ? [{ value: result.intel.upi, confidence: 95, timestamp: Date.now() }] : [],
          bankDetails: result.intel.bank ? [{ value: result.intel.bank, confidence: 95, timestamp: Date.now() }] : [],
          ifscCodes: result.intel.ifsc ? [{ value: result.intel.ifsc, confidence: 95, timestamp: Date.now() }] : [],
          phoneNumbers: result.intel.phone ? [{ value: result.intel.phone, confidence: 95, timestamp: Date.now() }] : [],
          links: result.intel.url ? [{ value: result.intel.url, confidence: 95, timestamp: Date.now() }] : [],
          cryptoWallets: [], fakeIdentities: []
        };
        onIntelExtracted(info);

        if (result.intel.upi || result.intel.phone) {
          syncIntelligence(updatedMessages, result.intel);
        }
      }
    } catch (e) {
      console.error(e);
    } finally {
      setIsTyping(false);
    }
  };

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTyping) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);
    setTimeout(() => runAgenticTurn(updatedMessages), 100);
  };

  return (
    <div className="glass-panel rounded-[3.5rem] border border-white/10 flex flex-col h-full overflow-hidden relative shadow-2xl">
      <div className="p-8 bg-black/70 border-b border-white/5 flex items-center justify-between backdrop-blur-3xl z-20">
        <div className="flex items-center space-x-6">
          <div className={`w-14 h-14 rounded-2xl border flex items-center justify-center transition-all duration-500 relative ${activeMode === 'honeypot' ? 'bg-orange-600/10 border-orange-500/30' : 'bg-blue-600/10 border-blue-500/30'}`}>
             {isSynthesizing && <div className="absolute inset-0 bg-blue-500/20 rounded-2xl animate-ping" />}
             <svg className={`w-7 h-7 ${activeMode === 'honeypot' ? 'text-orange-500' : 'text-blue-500'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
               <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 4.354a4 4 0 110 5.292M15 21H3v-1a6 6 0 0112 0v1zm0 0h6v-1a6 6 0 00-9-5.197M13 7a4 4 0 11-8 0 4 4 0 018 0z" />
             </svg>
          </div>
          <div>
            <h3 className="text-[10px] font-black text-white uppercase tracking-[0.4em]">Decoy Agent Active</h3>
            <span className={`text-[8px] font-black ${activeMode === 'honeypot' ? 'text-orange-500' : 'text-blue-500'} uppercase`}>{activeMode} mode</span>
          </div>
        </div>

        {/* Psychological Tracker */}
        <div className="flex space-x-8 px-6 border-x border-white/5 mx-6">
           <div className="space-y-1">
              <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Scammer Greed</div>
              <div className="w-24 h-1 bg-white/5 rounded-full overflow-hidden">
                 <div className="h-full bg-emerald-500 transition-all duration-1000" style={{ width: `${psychState.greed}%` }} />
              </div>
           </div>
           <div className="space-y-1">
              <div className="text-[8px] font-black text-slate-500 uppercase tracking-widest">Scammer Suspicion</div>
              <div className="w-24 h-1 bg-white/5 rounded-full overflow-hidden">
                 <div className="h-full bg-red-500 transition-all duration-1000" style={{ width: `${psychState.suspicion}%` }} />
              </div>
           </div>
        </div>

        <div className="flex items-center space-x-4">
          <div className="flex bg-white/5 rounded-xl p-1 border border-white/10">
            <button onClick={() => setChannelMode('chat')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${channelMode === 'chat' ? 'bg-blue-600 text-white' : 'text-slate-500'}`}>Chat</button>
            <button onClick={() => setChannelMode('voice')} className={`px-4 py-2 rounded-lg text-[9px] font-black uppercase transition-all ${channelMode === 'voice' ? 'bg-blue-600 text-white' : 'text-slate-500'}`}>Voice</button>
          </div>
        </div>
      </div>

      <div className="flex-1 flex flex-col overflow-hidden bg-[radial-gradient(circle_at_50%_0%,_#0f172a_0%,_#020617_100%)]">
        <div ref={scrollRef} className="flex-1 overflow-y-auto p-10 space-y-12 no-scrollbar custom-scrollbar">
          {initialMessages.map((m, idx) => (
            <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'} animate-in slide-in-from-bottom-2 duration-300`}>
              <div className={`max-w-[85%] rounded-[2rem] px-8 py-5 text-[15px] leading-relaxed shadow-2xl ${
                m.role === 'scammer' ? 'bg-slate-900 text-slate-100 border border-white/10' 
                : 'bg-blue-600 text-white border border-blue-400/30'
              }`}>
                {m.content}
              </div>
            </div>
          ))}
          {isTyping && (
            <div className="flex flex-col items-end space-y-2 animate-pulse">
               <div className="text-[10px] font-black uppercase text-blue-500 tracking-widest flex items-center">
                  <span className="mr-2">Synthesizing Multilingual Bait</span>
                  <div className="flex space-x-1">
                     <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" />
                     <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.2s]" />
                     <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce [animation-delay:0.4s]" />
                  </div>
               </div>
            </div>
          )}
          {isSynthesizing && (
            <div className="flex flex-col items-end space-y-2">
               <div className="text-[10px] font-black uppercase text-emerald-500 tracking-widest flex items-center">
                  <span className="mr-2">Transmitting Neural Audio</span>
                  <div className="w-4 h-4 rounded-full border border-emerald-500/50 flex items-center justify-center">
                     <div className="w-1.5 h-1.5 bg-emerald-500 rounded-full animate-ping" />
                  </div>
               </div>
            </div>
          )}
        </div>

        <div className="p-10 bg-black/80 border-t border-white/5">
          <form onSubmit={(e) => {
            e.preventDefault();
            const target = e.target as any;
            handleManualScammerReply(target.reply.value);
            target.reply.value = '';
          }} className="flex space-x-6">
            <input name="reply" disabled={isTyping} autoComplete="off" placeholder=">>> INPUT SCAMMER REPLY (e.g., 'Payment kahan hai?')" className="flex-1 bg-white/5 border border-white/10 rounded-[2rem] px-8 py-5 text-sm text-white font-mono focus:ring-1 focus:ring-blue-500 outline-none transition-all" />
            <button type="submit" disabled={isTyping} className="bg-blue-600 hover:bg-blue-500 px-10 rounded-[2rem] text-[11px] font-black uppercase transition-all shadow-lg active:scale-95 disabled:opacity-50">Send</button>
          </form>
        </div>
      </div>
    </div>
  );
};

