import React, { useState, useRef, useEffect } from 'react';
import { askTutor } from '../services/tutorService';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';

interface Message {
  role: 'user' | 'model';
  text: string;
}

const RakshakTutor: React.FC<{ onClose: () => void }> = ({ onClose }) => {
  const [messages, setMessages] = useState<Message[]>([
    { role: 'model', text: "Namaste! Main aapka Rakshak Tutor hoon. Aapko kisi scam se bachna hai ya is app ke baare mein kuch poochna hai? I am here to help you!" }
  ]);
  const [input, setInput] = useState('');
  const [isTyping, setIsTyping] = useState(false);
  const [isVoiceActive, setIsVoiceActive] = useState(false);
  const scrollRef = useRef<HTMLDivElement>(null);

  // Live Audio Refs
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages, isTyping, isVoiceActive]);

  // Audio Utilities
  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) binary += String.fromCharCode(bytes[i]);
    return btoa(binary);
  }

  function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) int16[i] = data[i] * 32768;
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  }

  const startVoiceMode = async () => {
    setIsVoiceActive(true);
    nextStartTimeRef.current = 0;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
            source.connect(scriptProcessor);
            scriptProcessor.connect(inputAudioContext.destination);
          },
          onmessage: async (msg: LiveServerMessage) => {
            // Handle Transcriptions
            if (msg.serverContent?.inputTranscription) {
              const text = msg.serverContent.inputTranscription.text;
              setMessages(prev => {
                if (prev[prev.length - 1]?.role === 'user' && prev[prev.length - 1]?.text.startsWith('[Voice]')) {
                   return [...prev.slice(0, -1), { role: 'user', text: `[Voice] ${text}` }];
                }
                return [...prev, { role: 'user', text: `[Voice] ${text}` }];
              });
            }
            if (msg.serverContent?.outputTranscription) {
              const text = msg.serverContent.outputTranscription.text;
              setMessages(prev => {
                if (prev[prev.length - 1]?.role === 'model' && !prev[prev.length - 1]?.text.includes("Namaste")) {
                   return [...prev.slice(0, -1), { role: 'model', text: text }];
                }
                return [...prev, { role: 'model', text: text }];
              });
            }

            // Handle Audio Playback
            const base64Audio = msg.serverContent?.modelTurn?.parts?.[0]?.inlineData?.data;
            if (base64Audio && audioContextRef.current) {
              const ctx = audioContextRef.current;
              nextStartTimeRef.current = Math.max(nextStartTimeRef.current, ctx.currentTime);
              const audioBuffer = await decodeAudioData(decodeBase64(base64Audio), ctx);
              const source = ctx.createBufferSource();
              source.buffer = audioBuffer;
              source.connect(ctx.destination);
              source.addEventListener('ended', () => sourcesRef.current.delete(source));
              source.start(nextStartTimeRef.current);
              nextStartTimeRef.current += audioBuffer.duration;
              sourcesRef.current.add(source);
            }

            if (msg.serverContent?.interrupted) {
              for (const s of sourcesRef.current.values()) { s.stop(); sourcesRef.current.delete(s); }
              nextStartTimeRef.current = 0;
            }
          },
          onerror: (e) => console.error("Tutor Voice Error", e),
          onclose: () => stopVoiceMode(),
        },
        config: {
          responseModalities: [Modality.AUDIO],
          inputAudioTranscription: {},
          outputAudioTranscription: {},
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName: 'Zephyr' } } },
          systemInstruction: `You are Bharat Cyber Rakshak Tutor. 
          You are speaking to the user in a real-time voice call.
          Be calm, friendly, and help them with cyber safety. 
          Speak in simple English, Hindi, or Hinglish based on what they use.
          Always guide them clearly if they are in a scam situation.`
        }
      });

      sessionRef.current = await sessionPromise;
    } catch (err) {
      console.error("Voice mode failed", err);
      setIsVoiceActive(false);
    }
  };

  const stopVoiceMode = () => {
    if (sessionRef.current) sessionRef.current.close();
    setIsVoiceActive(false);
    if (audioContextRef.current) audioContextRef.current.close();
  };

  const handleSend = async (e?: React.FormEvent) => {
    e?.preventDefault();
    if (!input.trim() || isTyping) return;

    const userMsg = input;
    setInput('');
    setMessages(prev => [...prev, { role: 'user', text: userMsg }]);
