        {isTyping && (
          <div className="flex justify-start">
            <div className="bg-slate-800 px-5 py-3 rounded-2xl rounded-bl-none border border-white/5 flex space-x-1">
              <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-bounce" />
