        )}
      </div>

      {/* Input Area */}
      <div className="p-4 bg-black/40 border-t border-white/5">
        <div className="flex items-center space-x-3">
          <button 
            type="button"
            onClick={isVoiceActive ? stopVoiceMode : startVoiceMode}
