            }`}
            title={isVoiceActive ? "Stop Voice Mode" : "Start Voice Call"}
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              {isVoiceActive ? (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" />
              ) : (
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
              )}
            </svg>
          </button>

          <form onSubmit={handleSend} className="flex-1 relative">
            <input 
              value={input}
              onChange={(e) => setInput(e.target.value)}
              disabled={isTyping || isVoiceActive}
              placeholder={isVoiceActive ? "Voice Chat Active..." : "Type your question..."}
              className="w-full bg-slate-800 border border-white/10 rounded-full py-3 pl-5 pr-12 text-sm text-white focus:outline-none focus:ring-1 focus:ring-blue-500 disabled:opacity-50"
