    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Detect scam intent and extract initial data: "${message}"`,
      config: {
        responseMimeType: "application/json",
        tools: [{ googleSearch: {} }],
        systemInstruction: "You are a cyber-crime forensic investigator. Detect scam intent. Output JSON.",
        thinkingConfig: { thinkingBudget: 8000 }
      },
    });

    const analysis: ScamAnalysis = safeJsonParse(response.text);

    // Guardian, Hub, & Data Protection Layer
    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
      analysis.operationalReport = await generateOperationalReport(analysis);
      analysis.dataProtectionRecord = await generateDataProtectionRecord(analysis);
    }

    return analysis;
  });
};

