import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, generateOperationalReport, generateSpeech } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, OperationalReport, ExtractedItem } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onOperationalReportGenerated?: (report: OperationalReport) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onOperationalReportGenerated }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [isSynthesizing, setIsSynthesizing] = useState(false);
  const [isReporting, setIsReporting] = useState(false);
  const [activeMode, setActiveMode] = useState<"normal" | "honeypot">("normal");
  const scrollRef = useRef<HTMLDivElement>(null);
  const audioContextRef = useRef<AudioContext | null>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [initialMessages, isTyping, isSynthesizing]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result = await generateAgenticBait(sessionId, history, 'chat');

      const isEngagement = result.engagement?.active ?? result.is_scam;
      setActiveMode(isEngagement ? "honeypot" : "normal");

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.agent_reply, 
        timestamp: Date.now(),
        extractedData: result.extracted_intelligence,
        verdict: result.scam_type
      }];

      onMessagesUpdate(updatedMessages);

      if (result.extracted_intelligence) {
        const intel = result.extracted_intelligence;
        const mapToExtracted = (list: string[] | undefined): ExtractedItem<string>[] => 
          (list || []).map(val => ({ value: val, confidence: 95, timestamp: Date.now() }));

        const info: ExtractedInfo = {
          upiIds: mapToExtracted(intel.upi_ids),
          bankDetails: (intel.bank_accounts || []).map((acc: any) => ({ 
            value: `${acc.bank_name || 'BANK'}: ${acc.account_number}`, 
            confidence: 95, 
            timestamp: Date.now() 
          })),
          ifscCodes: (intel.bank_accounts || []).map((acc: any) => ({ 
            value: acc.ifsc || '', 
            confidence: 95, 
            timestamp: Date.now() 
          })).filter(i => i.value),
          phoneNumbers: mapToExtracted(intel.phone_numbers),
          links: mapToExtracted(intel.phishing_urls),
          cryptoWallets: [], 
          fakeIdentities: []
        };
        onIntelExtracted(info);
      }
    } catch (e) {
      console.error("Agentic Turn Error:", e);
    } finally {
      setIsTyping(false);
    }
  };

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTyping) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);
    setTimeout(() => runAgenticTurn(updatedMessages), 100);
  };

  return (
    <div className="bg-slate-50 rounded-[3rem] border border-slate-200 flex flex-col h-full overflow-hidden shadow-xl relative">
      <div className="p-8 bg-white border-b border-slate-100 flex items-center justify-between z-20">
        <div className="flex items-center space-x-6">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 relative ${activeMode === 'honeypot' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
             <span className="text-2xl">{activeMode === 'honeypot' ? '🎣' : '🕵️'}</span>
          </div>
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Evidence Collection Lab</h3>
            <span className="text-sm font-bold text-navy-900">Case ID: {sessionId}</span>
          </div>
        </div>

        <div className="flex space-x-6">
           <div className="text-center">
              <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Bank Details</div>
              <div className="text-sm font-black text-navy-900">{initialMessages.reduce((acc, m) => acc + (m.extractedData?.bank_accounts?.length || 0), 0)}</div>
           </div>
           <div className="text-center">
              <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">UPI Handles</div>
              <div className="text-sm font-black text-navy-900">{initialMessages.reduce((acc, m) => acc + (m.extractedData?.upi_ids?.length || 0), 0)}</div>
           </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar custom-scrollbar">
        {initialMessages.map((m, idx) => (
          <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'}`}>
            <div className={`max-w-[85%] rounded-[1.5rem] px-6 py-4 text-sm font-medium leading-relaxed shadow-sm ${
              m.role === 'scammer' ? 'bg-white text-slate-700 border border-slate-100' 
              : 'bg-navy-900 text-white'
            }`}>
              {m.content}
            </div>
            {m.extractedData && (m.extractedData.upi_ids?.length || 0) > 0 && (
              <div className="mt-2 text-[8px] font-black text-blue-600 uppercase tracking-widest bg-blue-50 px-3 py-1 rounded-full border border-blue-100">
                Intel Captured: {m.extractedData.upi_ids?.[0]}
              </div>
            )}
          </div>
        ))}
        {isTyping && (
          <div className="flex justify-end space-x-2">
             <div className="w-2 h-2 bg-navy-900 rounded-full animate-bounce" />
             <div className="w-2 h-2 bg-navy-900 rounded-full animate-bounce [animation-delay:0.2s]" />
             <div className="w-2 h-2 bg-navy-900 rounded-full animate-bounce [animation-delay:0.4s]" />
          </div>
        )}
      </div>

      <div className="p-8 bg-white border-t border-slate-100">
        <form onSubmit={(e) => {
          e.preventDefault();
          const target = e.target as any;
          handleManualScammerReply(target.reply.value);
          target.reply.value = '';
        }} className="flex space-x-4">
          <input 
            name="reply" 
            disabled={isTyping} 
            autoComplete="off" 
            placeholder="Type scammer's next message..." 
            className="flex-1 bg-slate-50 border border-slate-200 rounded-[1.5rem] px-6 py-4 text-sm outline-none focus:ring-2 focus:ring-blue-500/20" 
          />
          <button type="submit" disabled={isTyping} className="bg-navy-900 text-white px-8 rounded-[1.5rem] font-bold text-sm">Send</button>
        </form>
      </div>
    </div>
  );
};

export default BaitSession;

