export const analyzeMessage = async (message: string, historySignatures: ScamSignature[] = []): Promise<ScamAnalysis> => {
  return withRetry(async () => {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents: `Analyze this message for cyber-fraud intent: "${message}"`,
      config: {
        responseMimeType: "application/json",
        systemInstruction: "You are a cyber safety expert. Detect scams and output detailed JSON analysis.",
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    const analysis = safeJsonParse(response.text);
    if (analysis.isScam) {
      analysis.guardianGuidance = await generateGuardianGuidance(analysis);
