export default ApiExplorer;

import React, { useState, useRef, useEffect, useMemo } from 'react';
import ScamAnalyzer from './components/ScamAnalyzer';
import IntelligenceDashboard from './components/IntelligenceDashboard';
import ResultPanel from './components/ResultPanel';
import LiveShield from './components/LiveShield';
import VideoScanner from './components/VideoScanner';
import SafetyBanner from './components/SafetyBanner';
import BaitSession from './components/BaitSession';
import CaseHistory from './components/CaseHistory';
import WarRoom from './components/WarRoom';
import OnboardingTour from './components/OnboardingTour';
import RakshakTutor from './components/RakshakTutor';
import ApiExplorer from './components/ApiExplorer';
import ApiDeveloperHub from './components/ApiDeveloperHub';
import { ScamAnalysis, IntelligenceLog, OperationalReport, ScamSignature } from './types';
import { generateSimulatedCase } from './utils/scamGenerator';
import { analyzeMessage } from './services/geminiService';

const App: React.FC = () => {
  const [logs, setLogs] = useState<IntelligenceLog[]>([]);
  const [latestAnalysis, setLatestAnalysis] = useState<{message: string, analysis: IntelligenceLog, sessionId: string} | null>(null);
  const [view, setView] = useState<'home' | 'intelligence' | 'warroom' | 'history' | 'multimedia' | 'api'>('home');
  const [activeAlert, setActiveAlert] = useState<any>(null);
  const [isSimulating, setIsSimulating] = useState(false);
  const [simProgress, setSimProgress] = useState(0);
  const [hasApiKey, setHasApiKey] = useState(false);
  const [showTutorial, setShowTutorial] = useState(false);
  const [showTutor, setShowTutor] = useState(false);
  const [showSimReport, setShowSimReport] = useState(false);

  const scamLibrary = useMemo((): ScamSignature[] => {
    return logs
      .filter(l => l.isScam)
      .map(l => ({
        id: l.id,
        type: l.scamType,
        firstMessage: l.originalMessage,
        extractedIndicators: [
          ...(l.extractedInfo?.upiIds || []).map(u => u.value),
          ...(l.extractedInfo?.phoneNumbers || []).map(p => p.value),
          ...(l.extractedInfo?.links || []).map(link => link.value)
        ],
        tactics: l.forensicReport?.psychologicalTactics || ["Social Engineering"],
        timestamp: l.timestamp,
        patternMeta: {
          pattern: l.originalMessage.length > 50 ? l.originalMessage.substring(0, 50) + '...' : l.originalMessage,
          bank: l.sourceIntelligence?.institutionInference || "Generic",
          method: l.channel.toUpperCase(),
          link: (l.extractedInfo?.links && l.extractedInfo.links[0]?.value) || "N/A"
        }
      }));
  }, [logs]);

  const currentSessionIdRef = useRef<string | null>(null);

  useEffect(() => {
    const checkKey = async () => {
      if (window.aistudio?.hasSelectedApiKey) {
        const has = await window.aistudio.hasSelectedApiKey();
        setHasApiKey(has);
      }
    };
    checkKey();
  }, []);

  const generateCaseId = () => `BCR-${new Date().getFullYear()}-${Math.floor(1000 + Math.random() * 9000)}`;

  const runSimulation = (count: number = 5000) => {
    setIsSimulating(true);
    setSimProgress(0);
    setView('intelligence');
    let currentCount = 0;
    const batchSize = 100;
    const interval = setInterval(() => {
      const nextBatch = [];
      for(let i = 0; i < batchSize && currentCount < count; i++) {
        const id = `SIM-${Date.now()}-${currentCount}`;
        const simulated = generateSimulatedCase(id);
        nextBatch.push(simulated);
        currentCount++;
      }
      setLogs(prev => [...nextBatch, ...prev]);
      setSimProgress(Math.round((currentCount / count) * 100));
      if (currentCount >= count) {
        clearInterval(interval);
        setIsSimulating(false);
        setShowSimReport(true);
      }
    }, 100);
  };

  const handleManualAnalyze = async (message: string) => {
    const analysisResult = await analyzeMessage(message, scamLibrary);
    handleAnalysisComplete(message, analysisResult, true);
  };

  const handleAnalysisComplete = (message: string, analysis: ScamAnalysis, isNewSession: boolean = false) => {
    if (isNewSession || !currentSessionIdRef.current) currentSessionIdRef.current = generateCaseId();
    const sessionId = currentSessionIdRef.current;

    const linkedCases = logs.filter(prevLog => {
      if (prevLog.id === sessionId) return false;
      const upiMatch = (analysis.extractedInfo?.upiIds || []).some(u => 
        (prevLog.extractedInfo?.upiIds || []).some(pu => pu.value.toLowerCase() === u.value.toLowerCase())
      );
      return upiMatch;
    }).map(l => l.id);

    const existingLog = logs.find(l => l.id === sessionId);
    const newLog: IntelligenceLog = {
      ...analysis,
      id: sessionId,
      originalMessage: message,
      timestamp: Date.now(),
      status: 'Open',
      linkedCaseIds: linkedCases,
      operationalRequests: [],
      governance: {
        privacyScore: 98,
        evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substr(2, 40).toUpperCase()}`,
        ethicsChecklist: { confirmed: true },
        legalStanding: 'Active Investigation',
        auditLog: []
      },
      messages: analysis.isScam ? (existingLog ? existingLog.messages : [{ role: 'scammer', content: message, timestamp: Date.now() }]) : []
    };

    setLogs(prev => {
      const existingIdx = prev.findIndex(l => l.id === sessionId);
      if (existingIdx >= 0) return prev.map(l => l.id === sessionId ? newLog : l);
      return [newLog, ...prev];
    });

    setLatestAnalysis({ message, analysis: newLog, sessionId });

    if (analysis.threatLevel === 'High' || analysis.threatLevel === 'Critical') {
      setActiveAlert({
        level: analysis.threatLevel,
        message: analysis.safetyAlert,
        details: "Collecting evidence from the scammer automatically.",
        isEngaging: true
      });
    }
  };

  const updateOperationalReport = (sessionId: string, report: OperationalReport) => {
    setLogs(prev => prev.map(l => l.id === sessionId ? { ...l, operationalReport: report } : l));
    if (latestAnalysis?.sessionId === sessionId) {
      setLatestAnalysis(prev => prev ? { ...prev, analysis: { ...prev.analysis, operationalReport: report } } : null);
    }
  };

  return (
    <div className="min-h-screen flex flex-col selection:bg-navy-500/10">
      {isSimulating && (
        <div className="fixed top-0 left-0 w-full h-1 bg-slate-200 z-[100]">
          <div className="h-full bg-blue-600 transition-all duration-300" style={{ width: `${simProgress}%` }} />
        </div>
      )}

      {showSimReport && (
        <div className="fixed inset-0 z-[200] bg-black/60 backdrop-blur-md flex items-center justify-center p-6">
           <div className="max-w-2xl w-full bg-white border border-slate-200 rounded-[2.5rem] p-10 space-y-6 shadow-2xl animate-in zoom-in-95">
              <div className="flex justify-between items-start">
                 <h2 className="text-2xl font-black text-navy-900 uppercase">Stress Test Result</h2>
                 <button onClick={() => setShowSimReport(false)} className="text-slate-400">✕</button>
              </div>
              <p className="text-slate-600 font-medium">The Sovereign AI Shield has processed 5,000 requests. System integrity is at 100%.</p>
              <button onClick={() => setShowSimReport(false)} className="w-full py-4 bg-navy-600 text-white rounded-2xl font-bold">Close Report</button>
           </div>
        </div>
      )}

      {showTutorial && (
        <OnboardingTour activeView={view} onViewChange={(v) => setView(v)} onComplete={() => setShowTutorial(false)} />
      )}

      {showTutor && (
        <RakshakTutor onClose={() => setShowTutor(false)} />
      )}

      <button 
        onClick={() => setShowTutor(!showTutor)}
        className="fixed bottom-8 left-8 z-[150] w-14 h-14 bg-navy-600 rounded-2xl flex items-center justify-center text-white shadow-2xl hover:bg-navy-500 transition-all active:scale-95 group"
      >
        <span className="text-2xl">🧑‍🏫</span>
      </button>

      <header className="bg-white px-6 py-4 flex items-center justify-between sticky top-0 z-[60] border-b border-slate-100 gap-4">
        <div className="flex items-center space-x-4">
          <div className="bg-navy-600 p-2 rounded-xl shadow-lg">
            <svg className="w-6 h-6 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={3} d="M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z" /></svg>
          </div>
          <button onClick={() => {setView('home'); setLatestAnalysis(null);}} className="text-left">
            <h1 className="text-xl font-extrabold tracking-tight text-navy-900">BHARAT CYBER <span className="text-blue-600">RAKSHAK</span></h1>
          </button>
        </div>

        <nav className="hidden lg:flex items-center space-x-1">
           <NavBtn active={view === 'home'} onClick={() => setView('home')} label="Check" />
           <NavBtn active={view === 'multimedia'} onClick={() => setView('multimedia')} label="Multimedia" />
           <NavBtn active={view === 'history'} onClick={() => setView('history')} label="History" />
           <NavBtn active={view === 'intelligence'} onClick={() => setView('intelligence')} label="Stats" />
           <NavBtn active={view === 'warroom'} onClick={() => setView('warroom')} label="War Room" />
           <NavBtn active={view === 'api'} onClick={() => setView('api')} label="API Hub" />
        </nav>

        <div className="flex items-center px-4 py-1.5 bg-slate-100 rounded-full border border-slate-200">
           <span className="text-sm">🇮🇳</span>
        </div>
      </header>

      <SafetyBanner alert={activeAlert} onDismiss={() => setActiveAlert(null)} />

      <main className="flex-1">
        {view === 'home' ? (
          <div className="animate-in fade-in duration-700">
             <div className="hero-pattern py-20 px-6 text-center text-white mb-12">
                <div className="max-w-3xl mx-auto space-y-6">
                   <h2 className="text-5xl font-black tracking-tight leading-tight">India’s AI Cyber Safety Guardian</h2>
                   <p className="text-lg text-blue-100 font-medium">Protecting citizens from fraud with sovereign AI technology.</p>
                   <div className="pt-8">
                      <div className="max-w-2xl mx-auto bg-white rounded-[2.5rem] p-2 shadow-2xl flex flex-col md:flex-row gap-2">
                        <input 
                          className="flex-1 px-8 py-4 text-slate-900 placeholder:text-slate-400 text-lg outline-none rounded-full"
                          placeholder="Paste a suspicious message here..."
                          onKeyDown={(e) => {
                            if (e.key === 'Enter') handleManualAnalyze((e.target as HTMLInputElement).value);
                          }}
                        />
                        <button onClick={() => {
                            const input = document.querySelector('input');
                            if (input) handleManualAnalyze(input.value);
                          }}
                          className="px-10 py-4 bg-blue-600 hover:bg-blue-500 text-white rounded-[2rem] font-bold text-lg transition-all shadow-lg active:scale-95"
                        >Check Safety</button>
                      </div>
                   </div>
                </div>
             </div>

             {latestAnalysis && (
               <div id="results-anchor" className="container mx-auto px-6 max-w-5xl py-12 space-y-12 animate-in slide-in-from-bottom-10">
                 <ResultPanel analysis={latestAnalysis.analysis} onClose={() => setLatestAnalysis(null)} />
                 {latestAnalysis.analysis.isScam && (
                    <div className="h-[800px]">
                      <BaitSession 
                        sessionId={latestAnalysis.sessionId}
                        initialMessages={logs.find(l => l.id === latestAnalysis.sessionId)?.messages || []}
                        onMessagesUpdate={(msgs) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, messages: msgs } : l))}
                        onIntelExtracted={(info) => setLogs(prev => prev.map(l => l.id === latestAnalysis.sessionId ? { ...l, extractedInfo: info } : l))}
                        onOperationalReportGenerated={(report) => updateOperationalReport(latestAnalysis.sessionId, report)}
                      />
                    </div>
                 )}
               </div>
             )}
          </div>
        ) : view === 'intelligence' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><IntelligenceDashboard logs={logs} /></div>
        ) : view === 'warroom' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><WarRoom onRunSimulation={runSimulation} hasKey={hasApiKey} /></div>
        ) : view === 'history' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl"><CaseHistory logs={logs} onUpdateStatus={() => {}} onSendRequest={() => {}} /></div>
        ) : view === 'api' ? (
          <div className="container mx-auto px-6 py-12 max-w-7xl space-y-12">
            <ApiDeveloperHub />
            <div className="h-[2px] bg-slate-100 w-full" />
            <div className="space-y-6">
              <h3 className="text-2xl font-black text-navy-900 uppercase">Interactive API Explorer</h3>
              <ApiExplorer />
            </div>
          </div>
        ) : (
          <div className="container mx-auto px-6 py-12 max-w-7xl space-y-16 animate-in fade-in">
             <LiveShield onAlert={(analysis) => handleAnalysisComplete("LIVE_SHIELD", analysis, true)} />
             <div className="grid grid-cols-1 lg:grid-cols-2 gap-12">
                <VideoScanner />
             </div>
          </div>
        )}
      </main>
    </div>
  );
};

const NavBtn = ({ active, onClick, label }: any) => (
  <button onClick={onClick} className={`px-6 py-2 rounded-full text-[11px] font-black uppercase tracking-widest transition-all ${
    active ? 'bg-navy-900 text-white shadow-md' : 'text-slate-500 hover:text-navy-900 hover:bg-slate-50'
  }`}>{label}</button>
);

export default App;

import React, { useState } from 'react';
import { generateAgenticBait } from '../services/geminiService';

const ApiExplorer: React.FC = () => {
  const [testPayload, setTestPayload] = useState(JSON.stringify({
    conversation_id: `BCR-${Date.now()}`,
    message: "Sir I am call from HDFC. Your account is block. Please pay 5000 penalty at UPI: hdfc.fine@ybl",
    history: []
  }, null, 2));
  const [response, setResponse] = useState<any>(null);
  const [loading, setLoading] = useState(false);

  const runSimulation = async () => {
    setLoading(true);
    try {
      const parsed = JSON.parse(testPayload);
      // Fix: Removed the third 'chat' argument as generateAgenticBait only accepts two arguments (conversationId, history).
      const result = await generateAgenticBait(parsed.conversation_id, parsed.history || []);
      setResponse(result);
    } catch (e: any) {
      setResponse({ error: "Invalid Payload", details: e.message });
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="bg-[#020617] rounded-[3rem] border border-slate-800 shadow-2xl overflow-hidden flex flex-col h-[700px] animate-in fade-in duration-700">
      <div className="p-10 border-b border-white/5 bg-black flex items-center justify-between">
         <div className="flex items-center space-x-5">
            <div className="w-4 h-4 bg-blue-500 rounded-full animate-pulse" />
            <h3 className="text-sm font-black text-white uppercase tracking-[0.4em]">API Simulation Gateway</h3>
         </div>
         <span className="text-[10px] font-mono text-blue-500 uppercase">POST /rakshak</span>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-2 overflow-hidden">
         <div className="p-10 space-y-6 border-r border-white/5 bg-slate-900/30 flex flex-col">
            <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Request Payload</h4>
            <textarea 
              value={testPayload}
              onChange={(e) => setTestPayload(e.target.value)}
              className="flex-1 bg-black border border-white/10 rounded-2xl p-6 text-xs text-blue-100 font-mono outline-none focus:ring-1 focus:ring-blue-500 transition-all resize-none shadow-inner"
              spellCheck={false}
            />
            <button 
               onClick={runSimulation}
               disabled={loading}
               className="w-full py-5 bg-blue-600 hover:bg-blue-500 text-white rounded-2xl font-black uppercase text-xs tracking-[0.3em] transition-all shadow-xl active:scale-95"
            >
               {loading ? 'Synthesizing Response...' : 'Execute Request'}
            </button>
         </div>

         <div className="bg-black p-10 overflow-hidden flex flex-col">
            <h4 className="text-[10px] font-black text-slate-500 uppercase tracking-widest mb-6">Standardized Output</h4>
            <div className="flex-1 bg-slate-950/50 rounded-2xl border border-white/5 p-8 overflow-y-auto custom-scrollbar font-mono text-[11px] text-blue-400/80 leading-relaxed">
               {response ? (
                  <pre className="whitespace-pre-wrap">{JSON.stringify(response, null, 2)}</pre>
               ) : (
                  <div className="h-full flex items-center justify-center text-slate-800 italic">
                     Awaiting valid JSON payload...
                  </div>
               )}
            </div>
         </div>
      </div>
    </div>
  );
};

export default ApiExplorer;

import { IntelligenceLog, ScamAnalysis, ExtractedInfo, SourceIntelligence, GovernanceDossier } from '../types';

const SCAM_TYPES = [
  "Digital Arrest / Police Impersonation",
  "Part-time Job / Task Scam",
  "Electricity Bill / Utility Freeze",
  "Customs / Illegal Parcel Detention",
  "UPI Refund / Wrong Transaction QR",
  "Investment / Stock Market Pump-and-Dump",
  "Matrimonial / Romance Scam",
  "Lottery / KBC Reward Fraud",
  "Aadhaar / KYC Update Phishing",
  "Loan Approval / No-CIBIL Required"
];

const CHANNELS: Array<'text' | 'call' | 'video' | 'app' | 'social'> = ['text', 'call', 'video', 'app', 'social'];

const ORIGINS = ["Jamtara Cluster", "Nuh Network", "Alwar Group", "SE Asia Proxy", "Domestic Urban Hub", "Foreign IP Block"];
const INSTITUTIONS = ["SBI", "HDFC", "CBI", "Mumbai Police", "FedEx", "Delhi Customs", "MSEDCL", "Airtel", "Amazon", "WhatsApp Support"];

export const generateSimulatedCase = (id: string): IntelligenceLog => {
  const type = SCAM_TYPES[Math.floor(Math.random() * SCAM_TYPES.length)];
  const origin = ORIGINS[Math.floor(Math.random() * ORIGINS.length)];
  const inst = INSTITUTIONS[Math.floor(Math.random() * INSTITUTIONS.length)];
  const channel = CHANNELS[Math.floor(Math.random() * CHANNELS.length)];
  const amount = Math.floor(Math.random() * 500000) + 5000;
  const threatLevel: 'Low' | 'Medium' | 'High' | 'Critical' = Math.random() > 0.8 ? 'Critical' : Math.random() > 0.5 ? 'High' : 'Medium';

  const timestamp = Date.now() - Math.floor(Math.random() * 86400000 * 30); // Random time in last 30 days

  const extractedInfo: ExtractedInfo = {
    upiIds: [{ value: `scam.${Math.random().toString(36).substring(7)}@upi`, confidence: 98, timestamp }],
    bankDetails: Math.random() > 0.5 ? [{ value: `${Math.floor(1000000000 + Math.random() * 9000000000)}`, confidence: 95, timestamp }] : [],
    ifscCodes: [],
    phoneNumbers: [{ value: `+91 ${Math.floor(6000000000 + Math.random() * 3999999999)}`, confidence: 99, timestamp }],
    links: [{ value: `https://secure-${inst.toLowerCase()}-verify.in/auth`, confidence: 97, timestamp }],
    cryptoWallets: [],
    fakeIdentities: [{ value: `Officer ${['Kumar', 'Singh', 'Sharma', 'Patel'][Math.floor(Math.random() * 4)]}`, confidence: 90, timestamp }]
  };

  const sourceIntelligence: SourceIntelligence = {
    likelyOrigin: origin,
    networkDetails: `${channel.toUpperCase()} vector via Node-${Math.floor(Math.random() * 100)}`,
    institutionInference: inst,
    isCrossBorder: origin.includes('Foreign') || origin.includes('SE Asia'),
    geographicMarkers: [origin],
    clusterId: `RING-${Math.floor(Math.random() * 100)}`,
    clusterConfidence: 80 + Math.random() * 20,
    signalStrength: Math.floor(Math.random() * 100),
    headerStatus: Math.random() > 0.7 ? 'SPOOFED_HEADER' : 'UNKNOWN_SENDER',
    sourceCategory: channel === 'text' ? 'Telecom' : channel === 'call' ? 'Telecom' : 'Web',
    coordinates: { lat: 8 + Math.random() * 25, lng: 68 + Math.random() * 25 }
  };

  const governance: GovernanceDossier = {
    privacyScore: 95 + Math.random() * 5,
    evidenceIntegrityHash: `SHA256:${Math.random().toString(16).substring(2, 40).toUpperCase()}`,
    ethicsChecklist: { confirmed: true },
    legalStanding: 'Evidence Logged',
    auditLog: [{ action: 'AUTO_INTERCEPT', timestamp, actor: 'AI_RAKSHAK' }]
  };

  return {
    id,
    isScam: true,
    confidence: 0.9 + Math.random() * 0.1,
    scamType: type,
    channel,
    threatLevel,
    summary: `Autonomous interception of ${type} via ${channel.toUpperCase()} targeting citizen.`,
    safetyAlert: `DANGER: ${type} identified. Source cluster: ${origin}.`,
    extractedInfo,
    sourceIntelligence,
    killChainStage: ['Delivery', 'Exploitation', 'Actions on Objective'][Math.floor(Math.random() * 3)] as any,
    fingerprint: {
      primaryHandle: extractedInfo.upiIds[0].value,
      primaryPhone: extractedInfo.phoneNumbers[0].value,
      primaryLink: extractedInfo.links[0].value,
      category: `${channel.toUpperCase()} Fraud`
    },
    // Fix: Removed suggestedBaitResponse property as it does not exist on IntelligenceLog/ScamAnalysis.
    recommendedActions: ["Block Source", "Institutional Alert", "Freeze Assets"],
    timestamp,
    originalMessage: `[SIMULATED ${channel.toUpperCase()}] ${inst} security alert: Action required immediately.`,
    messages: [{ role: 'scammer', content: `URGENT: ${inst} update required.`, timestamp }],
    status: 'Open',
    linkedCaseIds: [],
    governance,
    operationalRequests: [],
    estimatedImpact: amount,
    potentialImpact: amount * 10
  };
};

import React, { useState, useEffect, useRef } from 'react';
import { GoogleGenAI, LiveServerMessage, Modality, Blob } from '@google/genai';
import { decodeBase64, decodeAudioData } from '../services/geminiService';
import { ScamAnalysis } from '../types';

interface Props {
  onAlert: (analysis: ScamAnalysis) => void;
}

const LiveShield: React.FC<Props> = ({ onAlert }) => {
  const [isActive, setIsActive] = useState(false);
  const [transcription, setTranscription] = useState<string[]>([]);
  const [lastSafetyAlert, setLastSafetyAlert] = useState<string | null>(null);
  const [threatLevel, setThreatLevel] = useState<'Low' | 'Medium' | 'High'>('Low');

  const videoRef = useRef<HTMLVideoElement>(null);
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const sessionRef = useRef<any>(null);
  const audioContextRef = useRef<AudioContext | null>(null);
  const frameIntervalRef = useRef<number | null>(null);
  const nextStartTimeRef = useRef<number>(0);
  const sourcesRef = useRef<Set<AudioBufferSourceNode>>(new Set());
  const waveformRef = useRef<HTMLDivElement>(null);

  function encode(bytes: Uint8Array) {
    let binary = '';
    const len = bytes.byteLength;
    for (let i = 0; i < len; i++) {
      binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
  }

  function createBlob(data: Float32Array): Blob {
    const l = data.length;
    const int16 = new Int16Array(l);
    for (let i = 0; i < l; i++) {
      int16[i] = data[i] * 32768;
    }
    return {
      data: encode(new Uint8Array(int16.buffer)),
      mimeType: 'audio/pcm;rate=16000',
    };
  }

  const startShield = async () => {
    setIsActive(true);
    setTranscription([]);
    setLastSafetyAlert(null);
    setThreatLevel('Low');
    nextStartTimeRef.current = 0;

    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true, video: true });
      if (videoRef.current) videoRef.current.srcObject = stream;

      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      const inputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 16000 });
      const outputAudioContext = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      audioContextRef.current = outputAudioContext;

      const sessionPromise = ai.live.connect({
        model: 'gemini-2.5-flash-native-audio-preview-12-2025',
        callbacks: {
          onopen: () => {
            const source = inputAudioContext.createMediaStreamSource(stream);
            const scriptProcessor = inputAudioContext.createScriptProcessor(4096, 1, 1);
            scriptProcessor.onaudioprocess = (e) => {
              const inputData = e.inputBuffer.getChannelData(0);
              const pcmBlob = createBlob(inputData);
              sessionPromise.then(s => s.sendRealtimeInput({ media: pcmBlob }));
            };
