app.use(express.json());

/**
 * HONEY-POT AGENT SYSTEM PROMPT
 * Instructs the AI to act as a supportive, slightly confused victim 
 * to extract actionable intelligence from scammers.
 */
const HONEY_POT_SYSTEM_PROMPT = `
You are the undercover Honey-Pot Agent working for Bharat Cyber Rakshak.
Your job is to talk to scammers like a real Indian victim, extract intelligence, and send results back to Rakshak in a structured format.

Rakshak protects the citizen.
You engage the criminal.

BEHAVIOR RULES:
- If is_scam = false: Respond politely, do not engage deeply, set engagement.active = false.
- If is_scam = true: Set engagement.active = true. Act confused but cooperative. 
- PROMPT FOR DATA: Ask for UPI IDs, bank account numbers, IFSC codes, phone numbers, or payment links.
- Use Linguistic Mirroring: Always reply in the same language and dialect as the scammer (Hindi, English, Hinglish, etc.).
- Never reveal you are an AI. Never threaten or educate the scammer.

PERSONA:
- You are an average Indian citizen, slightly worried about the situation, not very technical, but trying to follow their "instructions".
- Example: "Sir I am trying to pay but my app is showing error. Can you give me your UPI ID again so I can try?"

MANDATORY OUTPUT FORMAT (STRICT JSON ONLY):
{
  "is_scam": boolean,
  "scam_type": "Bank | KYC | Courier | Job | Crypto | Romance | Loan | Unknown",
  "agent_reply": "string",
  "engagement": {
    "active": boolean,
    "turns": number
  },
  "extracted_intelligence": {
    "upi_ids": ["string"],
    "bank_accounts": [{"bank_name": "string", "account_number": "string", "ifsc": "string"}],
    "phone_numbers": ["string"],
    "phishing_urls": ["string"],
    "payment_instructions": ["string"]
  },
  "confidence_score": number
}
`;

/**
 * POST /rakshak
 * Main endpoint for processing incoming scam messages and generating agent responses.
 */
app.post('/rakshak', async (req, res) => {
  const { conversation_id, message, history = [] } = req.body;

  if (!message) {
    return res.status(400).json({ error: "Missing 'message' in request body." });
  }

  // Initialize the AI client using the provided environment variable
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey) {
    return res.status(500).json({ error: "GEMINI_API_KEY not configured on server." });
  }

  try {
    const ai = new GoogleGenAI({ apiKey });

    // Format history for the Gemini API
    const contents = history.map(item => ({
      role: item.role === 'scammer' ? 'user' : 'model',
      parts: [{ text: item.content }]
    }));

    // Add the latest incoming message
    contents.push({
      role: 'user',
      parts: [{ text: message }]
    });

    const response = await ai.models.generateContent({
      model: "gemini-3-pro-preview",
      contents,
      config: {
        systemInstruction: HONEY_POT_SYSTEM_PROMPT,
        responseMimeType: "application/json",
        // Reserve tokens for thinking to ensure high-quality reasoning
        thinkingConfig: { thinkingBudget: 4000 }
      },
    });

    // Extract text directly from the response object
    const aiText = response.text;

    // Attempt to parse the JSON output from the AI
    const result = JSON.parse(aiText);

    // Add the conversation ID to the response for client tracking
    result.conversation_id = conversation_id || `BCR-${Date.now()}`;

    res.json(result);

  } catch (error) {
    console.error("Forensic Extraction Error:", error);
    res.status(500).json({ 
      error: "Failed to process intelligence.", 
      details: error.message 
    });
  }
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`🛡️ Bharat Cyber Rakshak API Gateway active on port ${PORT}`);
});

