import React, { useState, useEffect, useRef } from 'react';
import { generateAgenticBait, generateOperationalReport } from '../services/geminiService';
import { ChatMessage, ExtractedInfo, AgentResponse, AgentIntelligence } from '../types';

interface Props {
  sessionId: string;
  initialMessages: ChatMessage[];
  onMessagesUpdate: (messages: ChatMessage[]) => void;
  onIntelExtracted: (info: ExtractedInfo) => void;
  onOperationalReportGenerated?: (report: any) => void;
}

const BaitSession: React.FC<Props> = ({ sessionId, initialMessages, onMessagesUpdate, onIntelExtracted, onOperationalReportGenerated }) => {
  const [isTyping, setIsTyping] = useState(false);
  const [activeMode, setActiveMode] = useState<"normal" | "honeypot">("normal");
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' });
    }
  }, [initialMessages, isTyping]);

  const runAgenticTurn = async (currentMessages: ChatMessage[]) => {
    setIsTyping(true);
    try {
      const history = currentMessages.map(m => ({ role: m.role, content: m.content }));
      const result: AgentResponse = await generateAgenticBait(sessionId, history);

      setActiveMode(result.engagement.active ? "honeypot" : "normal");

      const updatedMessages: ChatMessage[] = [...currentMessages, { 
        role: 'bot', 
        content: result.agent_reply, 
        timestamp: Date.now(),
        extractedData: result.extracted_intelligence,
        verdict: result.scam_type
      }];

      onMessagesUpdate(updatedMessages);

      // Map structured intel back to the main App state
      const intel = result.extracted_intelligence;
      const info: ExtractedInfo = {
        upiIds: (intel.upi_ids || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        bankDetails: (intel.bank_accounts || []).map(acc => ({ value: typeof acc === 'string' ? acc : JSON.stringify(acc), confidence: 95, timestamp: Date.now() })),
        ifscCodes: (intel.ifsc_codes || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        phoneNumbers: (intel.phone_numbers || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        links: (intel.phishing_urls || []).map(v => ({ value: v, confidence: 95, timestamp: Date.now() })),
        cryptoWallets: [],
        fakeIdentities: []
      };

      onIntelExtracted(info);

      if (onOperationalReportGenerated && result.engagement.active) {
         const report = await generateOperationalReport(result, updatedMessages.map(m => `${m.role}: ${m.content}`).join('\n'));
         onOperationalReportGenerated(report);
      }
    } catch (e) {
      console.error("Agentic Turn Error:", e);
    } finally {
      setIsTyping(false);
    }
  };

  const handleManualScammerReply = async (reply: string) => {
    if (!reply.trim() || isTyping) return;
    const updatedMessages: ChatMessage[] = [...initialMessages, { role: 'scammer', content: reply, timestamp: Date.now() }];
    onMessagesUpdate(updatedMessages);
    setTimeout(() => runAgenticTurn(updatedMessages), 100);
  };

  const getCounter = (key: keyof AgentIntelligence) => {
    return initialMessages.reduce((acc, m) => acc + (m.extractedData?.[key]?.length || 0), 0);
  };

  return (
    <div className="bg-slate-50 rounded-[3rem] border border-slate-200 flex flex-col h-full overflow-hidden shadow-xl relative">
      <div className="p-8 bg-white border-b border-slate-100 flex items-center justify-between z-20">
        <div className="flex items-center space-x-6">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center transition-all duration-500 relative ${activeMode === 'honeypot' ? 'bg-orange-100 text-orange-600' : 'bg-blue-100 text-blue-600'}`}>
             <span className="text-2xl">{activeMode === 'honeypot' ? '🎣' : '🕵️'}</span>
          </div>
          <div>
            <h3 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.4em]">Autonomous Evidence Gathering</h3>
            <span className="text-sm font-bold text-navy-900">Agent Persona: Undercover Victim</span>
          </div>
        </div>

        <div className="flex space-x-6">
           <div className="text-center">
              <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Bank/IFSC Intel</div>
              <div className={`text-sm font-black transition-colors ${getCounter('upi_ids') + getCounter('bank_accounts') + getCounter('ifsc_codes') > 0 ? 'text-orange-600' : 'text-navy-900'}`}>
                {getCounter('upi_ids') + getCounter('bank_accounts') + getCounter('ifsc_codes')}
              </div>
           </div>
           <div className="text-center">
              <div className="text-[8px] font-black text-slate-400 uppercase tracking-widest">Digital Trails</div>
              <div className="text-sm font-black text-navy-900">
                {getCounter('phone_numbers') + getCounter('phishing_urls')}
              </div>
           </div>
        </div>
      </div>

      <div className="flex-1 overflow-y-auto p-10 space-y-8 no-scrollbar custom-scrollbar">
        {initialMessages.map((m, idx) => (
          <div key={idx} className={`flex flex-col ${m.role === 'scammer' ? 'items-start' : 'items-end'}`}>
            <div className={`max-w-[85%] rounded-[1.5rem] px-6 py-4 text-sm font-medium leading-relaxed shadow-sm ${
              m.role === 'scammer' ? 'bg-white text-slate-700 border border-slate-100' 
              : 'bg-navy-900 text-white'
            }`}>
